def digest(raw):
    return hashlib.sha256(raw).hexdigest()

def checked(raw,expected,label):
    if digest(raw)!=expected['sha256'] or len(raw)!=expected['bytes']:
        raise ValueError('Changed complete source '+label)

def replace_exact(text,old,new,count,label):
    if text.count(old)!=count:
        raise ValueError('Changed exact complete-source patch '+label)
    return text.replace(old,new)

def inverse_exact(text,patch,label):
    for position in reversed(patch['new_positions']):
        end=position+len(patch['new'])
        if text[position:end]!=patch['new']:
            raise ValueError('Changed exact inverse source span '+label)
        text=text[:position]+patch['old']+text[end:]
    return text

def generate(repo,outdir,verify_existing=False):
    source=Path(repo).resolve()/'topics/visible-flex-larger-amplitude/scripts/resume_20261126'
    destination=Path(outdir).resolve()
    generated={}
    for entry in PLAN['patch_sources']:
        parent=(source/entry['parent']['name']).read_bytes()
        checked(parent,entry['parent'],entry['parent']['name'])
        text=parent.decode('utf-8')
        for index,patch in enumerate(entry['patches']):
            text=replace_exact(text,patch['old'],patch['new'],patch['count'],entry['name']+':'+str(index))
        raw=text.encode('utf-8')
        checked(raw,entry,entry['name'])
        reverse=text
        for index,patch in enumerate(reversed(entry['patches'])):
            reverse=inverse_exact(reverse,patch,entry['name']+':inverse:'+str(index))
        if reverse.encode('utf-8')!=parent:
            raise ValueError('The complete inverse differs '+entry['name'])
        generated[entry['name']]=raw
    for entry in PLAN['complete_literal_sources']:
        raw=entry['body'].encode('utf-8')
        checked(raw,entry,entry['name'])
        generated[entry['name']]=raw
    if not verify_existing:
        destination.mkdir(parents=True,exist_ok=True)
    records={}
    for name,raw in generated.items():
        path=destination/name
        if verify_existing:
            if path.read_bytes()!=raw:raise ValueError('Changed complete generated file '+name)
        else:
            if path.exists() and path.read_bytes()!=raw:
                raise ValueError('Do not overwrite another complete source '+str(path))
            if not path.exists():path.write_bytes(raw)
        records[name]=dict(path=str(path),bytes=len(raw),sha256=digest(raw),whole_expected_source_equal=True)
    return dict(schema=PLAN['schema'],complete_source_text_reproduced=True,
        scientific_execution_performed=False,Python_AST_or_compile_performed=False,
        complete_outputs=records)

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--repo',type=Path,required=True)
    parser.add_argument('--outdir',type=Path,required=True)
    parser.add_argument('--verify-existing',action='store_true')
    args=parser.parse_args()
    print(json.dumps(generate(args.repo,args.outdir,args.verify_existing),sort_keys=True))

if __name__=='__main__':
    main()
